    s = str(v or '').strip()
    try:
        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        pass
    try:
        return datetime.datetime.fromisoformat(s[:10] + 'T12:00')
    except Exception:
        return datetime.datetime(2026, 1, 1, 12, 0)

