def prev_biz(d, inclusive):
    x = d if inclusive else d - datetime.timedelta(days=1)
    while not is_biz(x):
        x = x - datetime.timedelta(days=1)
    return x

def add_biz(d, n):
    x = d
    for _ in range(int(n)):
        x = next_biz(x, False)
    return x

